-- Migración 0003. Crea EXPEDICIONES.
-- Una expedición abierta es la carga de una unidad: al crearla, la unidad está vacía.
-- FECHA_CIERRE se llena cuando la unidad sale de la nave e inicia el viaje.
-- La ubicación de salida es una referencia externa: no tiene llave foránea.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

CREATE TABLE "EXPEDICIONES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_UNIDAD" integer NOT NULL,
  "FECHA_CIERRE" timestamptz,
  "ID_UBICACION_SALIDA" integer,
  "CLAVE_UBICACION_SALIDA" text,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "EXPEDICIONES_ID_UNIDAD_FK"
    FOREIGN KEY ("ID_UNIDAD") REFERENCES "UNIDADES_TRANSPORTE" ("ID"),
  CONSTRAINT "EXPEDICIONES_FECHA_CIERRE_CHK" CHECK (
    "FECHA_CIERRE" IS NULL OR "FECHA_CIERRE" >= "CREADO_EN"
  ),
  CONSTRAINT "EXPEDICIONES_ID_UBICACION_SALIDA_CHK" CHECK (
    "ID_UBICACION_SALIDA" IS NULL OR "ID_UBICACION_SALIDA" > 0
  ),
  CONSTRAINT "EXPEDICIONES_CLAVE_UBICACION_SALIDA_CHK" CHECK (
    "CLAVE_UBICACION_SALIDA" IS NULL OR length(btrim("CLAVE_UBICACION_SALIDA")) > 0
  )
);

CREATE INDEX "EXPEDICIONES_ID_UNIDAD_IDX" ON "EXPEDICIONES" ("ID_UNIDAD");

CREATE UNIQUE INDEX "EXPEDICIONES_UNIDAD_ABIERTA_UQ"
  ON "EXPEDICIONES" ("ID_UNIDAD")
  WHERE "FECHA_CIERRE" IS NULL;
